def specialFilter(nums):
    def first_digit(n):
        while n >= 10:
            n //= 10
        return n

    def last_digit(n):
        return abs(n) % 10

    count = 0
    for num in nums:
        if num > 10 and first_digit(num) % 2 == 1 and last_digit(num) % 2 == 1:
            count += 1
    return count

